/**
 * Tables the game publishes per tier or per league that had no chart: the coin bonus a tier pays,
 * the cells an elite drops on it, and what a tournament placing pays in each league.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    tierCoinMultipliersData, eliteCellsByTierData, buildTournamentRewardsDataset
 * depends    src/charts/tables/types, src/data
 * used by    src/calculators/specs.generated, src/charts/datasets/index, src/charts/index, src/charts/tables/lookup
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import {
  ELITE_CELL_TIER_ROWS,
  TIER_COIN_BONUS_ROWS,
  TOURNAMENT_LEAGUES,
  getTournamentRewardsForLeague,
} from '../../data'
import type { SharedChartTableDataset } from '../tables/types'

type Dataset = SharedChartTableDataset<Record<string, unknown>>

/** The coin bonus each tier pays, as a multiplier on every coin earned there. */
export const tierCoinMultipliersData: Dataset = {
  title: 'Coin Bonus by Tier',
  columns: [
    { key: 'tier', label: 'Tier' },
    { key: 'coinBonus', label: 'Coin Bonus' },
  ],
  rows: TIER_COIN_BONUS_ROWS.map(row => ({ tier: row.tier, coinBonus: `x${row.coinBonus}` })),
}

/**
 * Cells per elite, from the first tier whose range is not simply 1 to the tier number. Below
 * that the rule is one line and has no rows here: an elite drops 1 to X cells on tier X.
 */
export const eliteCellsByTierData: Dataset = {
  title: 'Elite Cells per Kill by Tier',
  columns: [
    { key: 'tier', label: 'Tier' },
    { key: 'minimumCells', label: 'Minimum' },
    { key: 'maximumCells', label: 'Maximum' },
    { key: 'averageCells', label: 'Average' },
    { key: 'increase', label: 'Increase Over Prior Tier' },
  ],
  rows: ELITE_CELL_TIER_ROWS.map(row => ({
    tier: row.tier,
    minimumCells: row.minimumCells,
    maximumCells: row.maximumCells,
    averageCells: row.averageCells,
    increase: `${row.averageIncreaseFromPriorPercent}%`,
  })),
}

/** A league name as a chart id spells it: `Legend` is `legend`. */
const leagueSlug = (league: string): string => league.toLowerCase().replace(/[^a-z0-9]+/g, '-')

/**
 * What each placing in a league's tournament pays, or `null` when no league has that name.
 *
 * Keys are paid only in the leagues that list them, so the column is left out elsewhere rather
 * than printed as a column of zeros.
 */
export function buildTournamentRewardsDataset(league: string): Dataset | null {
  const wanted = leagueSlug(String(league ?? ''))
  const definition = TOURNAMENT_LEAGUES.find(entry => leagueSlug(entry.league) === wanted)
  if (!definition || !wanted) return null

  const rewards = getTournamentRewardsForLeague(definition.league)
  const paysKeys = rewards.some(row => row.keys > 0)

  return {
    title: `${definition.league} League Tournament Rewards`,
    columns: [
      { key: 'rank', label: 'Rank' },
      { key: 'gems', label: 'Gems' },
      { key: 'stones', label: 'Power Stones' },
      ...(paysKeys ? [{ key: 'keys', label: 'Keys' }] : []),
    ],
    rows: rewards.map(row => ({
      rank: row.rank,
      gems: row.gems,
      stones: row.stones,
      ...(paysKeys ? { keys: row.keys } : {}),
    })),
  }
}
